/* ---------- Invite ---------- */
.ivx{padding:16px;display:flex;flex-direction:column;gap:10px;max-width:420px;margin:0 auto;width:100%}
.ivx-h{display:flex;flex-direction:column;font-size:14px;margin:0 -14px 2px;padding:0 14px 12px;border-bottom:1px solid var(--line)}
.ivx-h b{font-weight:500}
.ivx-h .muted{font-size:12px}
.ivx-f{display:flex;align-items:center;flex-wrap:wrap;gap:5px;min-height:42px;padding:5px 5px 5px 8px;border-radius:12px;background:var(--chip);transition:box-shadow .25s,background .25s}
.ivx-f:focus-within{background:var(--surface);box-shadow:inset 0 0 0 1.5px var(--accent-mark,var(--accent)),0 0 0 4px var(--accent-bg)}
.ivx-chips{display:contents}
.ivx-ch{display:inline-flex;align-items:center;gap:5px;height:26px;padding:0 4px 0 4px;border-radius:8px;background:var(--surface);box-shadow:0 0 0 1px var(--line);font-size:12.5px;animation:popin .4s var(--ease) backwards}
.ivx-ch .av{width:18px;height:18px;font-size:8.5px}
.ivx-ch.bad{background:var(--bad-bg);color:var(--bad);box-shadow:none}
/* chips already on screen keep still when the row is redrawn; only a new one pops in */
.ivx-chips .ivx-ch.seen{animation:none}
.ivx-ch button{display:grid;color:var(--muted)}@media (hover:hover) and (pointer:fine){.ivx-ch button:hover{color:var(--fg)}}
.ivx-f input{flex:1;min-width:120px;border:0;outline:0;background:transparent;font:inherit;font-size:13px;color:var(--fg);height:28px}
.ivx-f input::placeholder{color:var(--muted)}
.ivx-role{display:flex;align-items:center;gap:4px;height:30px;padding:0 8px;border-radius:9px;font-size:12.5px;color:var(--fg2);margin-left:auto}
@media (hover:hover) and (pointer:fine){.ivx-role:hover{background:var(--hover)}}
.ivx-sg{display:flex;align-items:center;gap:6px;flex-wrap:wrap;font-size:12px}
.ivx-sg .chip .av{width:18px;height:18px;font-size:8.5px;margin-left:-6px}
.ivx-mem{display:flex;flex-direction:column}
.ivx-m{display:flex;align-items:center;gap:10px;padding:6px 2px;font-size:13px}
.ivx-m .av{width:26px;height:26px;font-size:10px}
.ivx-m .t{flex:1;display:flex;flex-direction:column}
.ivx-m .t span{font-size:11.5px;color:var(--muted)}
.ivx-m .r{font-size:12px;color:var(--muted)}
.ivx-m .r.pend{color:var(--warn)}
.ivx-ft{display:flex;justify-content:space-between;gap:6px}

DM.def('invite', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{chev}', I('chev-d','xs')).replace(/\{chk\}/g, I('check','xs')).replace('{link}', I('link','xs'));
  const chips = $('.ivx-chips', r), inp = $('.ivx-f input', r), go = $('.ivx-go', r), mem = $('.ivx-mem', r), sg = $('.ivx-sg', r);
  let E = [], role = 'Can edit', shown = new Set();
  const COL = ['var(--pl)','var(--pm)','var(--pt)','var(--pp)','var(--pk)'];
  const ok = e => /^\S+@\S+\.\S+$/.test(e);
  const ini = e => e.split('@')[0].slice(0, 2).toUpperCase();
  function paint(){ const seen = shown; shown = new Set(E); chips.innerHTML = E.map((e, i) => `<span class="ivx-ch${ok(e) ? '' : ' bad'}${seen.has(e) ? ' seen' : ''}" ${ok(e) ? '' : 'data-tip="Not a valid email"'}>${ok(e) ? AV(ini(e), COL[i % 5]) : I('alert','xs')}${e}<button aria-label="Remove ${e}">${I('x','xs')}</button></span>`).join('');
    $$('.ivx-ch button', chips).forEach((b, i) => b.onclick = () => { E.splice(i, 1); paint(); });
    const n = E.filter(ok).length; go.disabled = !n || E.some(e => !ok(e)); go.textContent = n > 1 ? `Send ${n} invites` : 'Send invite'; }
  function commit(){ const parts = inp.value.split(/[,\s]+/).map(s => s.trim()).filter(Boolean); if (!parts.length) return; parts.forEach(p => { if (!E.includes(p)) E.push(p); }); inp.value = ''; paint(); }
  inp.onkeydown = e => { if (e.key === 'Enter' || e.key === ',' || e.key === 'Tab'){ if (inp.value.trim()){ e.preventDefault(); commit(); } } else if (e.key === 'Backspace' && !inp.value && E.length){ E.pop(); paint(); } };
  inp.onpaste = () => setTimeout(commit, 0); inp.onblur = commit;
  [['ari@studio.com','AR','var(--pp)'],['sam@studio.com','SL','var(--pt)']].forEach(s => { const b = html(`<button class="chip sm">${AV(s[1], s[2])}${s[0].split('@')[0]}</button>`); sg.appendChild(b); b.onclick = () => { if (!E.includes(s[0])){ E.push(s[0]); paint(); } b.remove(); }; });
  $$('.ivx-rp .mi', r).forEach(m => m.addEventListener('click', () => { role = m.dataset.r; $$('.ivx-rp .mi', r).forEach(x => x.setAttribute('aria-checked', x === m)); swap($('.ivx-role span', r), role); }));
  const M = [['MK','var(--pl)','Maya Kim','Owner'],['JO','var(--pm)','Jon Ortiz','Can edit']];
  mem.innerHTML = M.map(m => `<div class="ivx-m">${AV(m[0], m[1])}<span class="t">${m[2]}</span><span class="r">${m[3]}</span></div>`).join('');
  go.onclick = () => c.run(async () => { go.innerHTML = '<span class="spin"></span>'; await c.wait(800); E.filter(ok).forEach((e, i) => { const el = html(`<div class="ivx-m">${AV(ini(e), COL[i % 5])}<span class="t">${e.split('@')[0]}<span>${e}</span></span><span class="r pend">Invited, ${role.toLowerCase()}</span></div>`); mem.appendChild(el); enter(el, i * 70); }); E = []; paint(); });
  const lk = $('.ivx-link', r); lk.onclick = () => { copied(lk, 'https://designme.dev/join/pricing-refresh'); const t = lk.lastChild; t.textContent = 'Link copied'; clearTimeout(lk._lt); lk._lt = setTimeout(() => { t.textContent = 'Copy link'; }, 1600); };
  paint();
  // the preview adds two people on its own; clicking, focusing or typing in it takes over, and what it had typed goes
  c.auto(900, () => c.run(async () => { await c.type(inp, 'dana@studio.com', { keep:true }); await c.step(40); commit(); await c.type(inp, ' lee@studio', { keep:true }); commit(); }));
});
